```openscad
// T-shaped nut for aluminium extrusion
// Print orientation: flange on bed (z = 0), neck pointing up (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
flange_w      = 14;   // flange width (Y)
flange_t      = 2;    // flange thickness (Z), z = 0..2
neck_w        = 7;    // neck width (Y)
neck_h        = 4;    // neck height above flange top (Z), 2..6
screw_d       = 4.5;  // central screw hole diameter
length_x      = 20;   // part length along X
eps           = 0.5;  // overshoot for clean cuts

total_h = flange_t + neck_h;  // overall height

module t_flange() {
    // bottom flange, full width down to the bed
    translate([-length_x/2, -flange_w/2, 0])
        cube([length_x, flange_w, flange_t]);
}

module t_neck() {
    // neck centred on the flange, from z = 2 up to z = 6
    translate([-length_x/2, 0, flange_t])
        cube([length_x, neck_w, neck_h]);
}

difference() {
    union() { t_flange(); t_neck(); }
    // screw hole through the whole part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
}
