```openscad
// T-shaped nut for aluminium extrusion slot
// Print orientation: flange on XY plane (z = 0), neck builds upward (+Z)

// ---------------- Parameters ----------------
flange_width   = 14;   // flange width along Y (mm)
flange_thick   = 2.5;  // flange thickness along Z (mm), z = 0 to 2.5
neck_width     = 7;    // neck width along Y (mm), centred on flange
neck_top_z     = 5.5;  // top of neck along Z (mm)
screw_d        = 4.5;  // central screw hole diameter (mm)
length_x       = 12;   // part length along X (mm), centred on origin
eps            = 0.5;  // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Upside-down T profile, extruded along X
    translate([-length_x / 2, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = length_x)
                polygon(points = [
                    // Bottom flange: x = -7 to 7, y = -7 to 7
                    for (sx = [-7, 7], sy = [-7, 7])
                        [sx, sy, 0],
                    // Neck: x = -3.5 to 3.5, y = -3.5 to 3.5, z = 2.5 to 5.5
                    for (sx = [-3.5, 3.5], sy = [-3.5, 3.5])
                        [sx, sy, neck_top_z]
                ]);

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2 * eps);
}
