```openscad
// T-shaped nut that slides into an aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck builds upward (+Z)
// The file uses the user's dimensions as if the part were centred on the origin.

$fn = 64;

// ---------- Dimensions (mm) ----------
flange_width   = 14;   // flange size in Y
flange_thick   = 2.5;  // flange thickness (z = 0 to 2.5)
neck_width     = 7;    // neck size in Y
neck_height    = 5.5;  // top of the neck (z = 0 to 5.5)
screw_d        = 4.5;  // central screw hole diameter
slot_length    = 12;   // part length along X
overcut        = 0.5;  // extension of the hole past the faces

// ---------- Model ----------
difference() {
    // Upside-down T profile: flange at the bottom, neck rising above it
    union() {
        // Flange: -7 .. 7 in Y, thickness 2.5, centred on origin in X
        translate([-slot_length / 2, -flange_width / 2, 0])
            cube([slot_length, flange_width, flange_thick]);

        // Neck: -3.5 .. 3.5 in Y, height 5.5, centred on origin in X
        translate([-slot_length / 2, -neck_width / 2, 0])
            cube([slot_length, neck_width, neck_height]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -overcut])
        cylinder(d = screw_d, h = neck_height + 2 * overcut);
}
