```openscad
// T-shaped nut for aluminium extrusion
// Print orientation: flange on bed (z = 0), neck pointing up (+Z)

$fn = 64;

// --- Flange ---
flange_len   = 20;   // length along X
flange_wid   = 12;   // width along Y
flange_thk   = 3;    // thickness (z = 0 .. 3)

// --- Neck ---
neck_len     = 20;   // length along X (same as flange)
neck_wid     = 8;    // width along Y
neck_hgt     = 4;    // height above flange (z = 3 .. 7)

// --- Screw hole ---
hole_d       = 5.5;  // through-hole diameter
hole_off     = 0;    // offset from centre (0 = centred)

// --- Derived ---
total_h      = flange_thk + neck_hgt;   // 7 mm overall height
eps          = 0.5;   // overcut for clean differences

difference() {
    // T profile
    union() {
        // Flange
        translate([-flange_len/2, -flange_wid/2, 0])
            cube([flange_len, flange_wid, flange_thk]);
        // Neck
        translate([-neck_len/2, -neck_wid/2, flange_thk])
            cube([neck_len, neck_wid, neck_hgt]);
    }

    // Screw hole
    translate([hole_off, 0, -eps])
        cylinder(d = hole_d, h = total_h + 2*eps);
}
