// Stiffened cover panel - flat plate with 4 transverse ribs
// Print orientation: plate flat on bed (z = 0), ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 5;     // rib height above plate top (mm), z = 2..7
rib_count   = 4;     // number of ribs
rib_pitch   = 16;    // centre-to-centre spacing of ribs (mm)
rib_offset  = 16;    // distance of outer rib centres from plate ends (mm)

overlap     = 0.5;   // rib overlap into plate for a clean union (mm)

$fn = 64;            // curve resolution (no curves here, set per rules)

// Derived
rib_x0 = -plate_len/2 + rib_offset;   // first rib centre (leftmost)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
