```openscad
// Stiffened cover panel
// Print orientation: plate flat on bed (z = 0), ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 50;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness (mm), z = 0..3

rib_count   = 4;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_hgt     = 5;     // rib height above plate top (mm), z = 3..8
rib_pitch   = 24;    // centre-to-centre spacing of ribs (mm)
rib_overlap = 0.01;  // small overlap into plate so ribs fuse with it

$fn = 64;

// ---------------- Derived ----------------
plate_x0 = -plate_len / 2;   // plate left end
plate_x1 = plate_len / 2;    // plate right end

// Ribs divide the length into 5 equal parts; their centres are 24 mm apart.
// The outer ones sit 24 mm from the ends of the plate.
function rib_x(i) = plate_x0 + rib_overlap + (i + 1) * rib_pitch;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([plate_x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Four ribs running the full width along Y
    for (i = [0 : rib_count - 1])
        translate([rib_x(i) - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_hgt]);
}
```

```openscad
// Cable bridge - rectangular block with 3 semicircular tunnels along Y at floor level
// Print orientation: base on the bed (z = 0), tunnels open downward

// ---------------- Parameters ----------------
block_len    = 60;    // block length along X (mm)
block_wid    = 50;    // block width along Y (mm)
block_ht     = 15;    // block height along Z (mm)

tunnel_d     = 10;    // tunnel diameter (mm); radius = 5 mm, axis at z = 0
tunnel_count = 3;     // number of tunnels
tunnel_pitch = 16;    // centre-to-centre spacing of tunnels along X (mm)

eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// ---------------- Derived ----------------
tunnel_r = tunnel_d / 2;
// first tunnel axis X position, centred on the origin
tunnel_x0 = -(tunnel_count - 1) * tunnel_pitch / 2;

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axis along Y, cutter extended above the top face
    for (i = [0 : tunnel_count - 1]) {
        translate([tunnel_x0 + i * tunnel_pitch, 0, 0])
            translate([0, 0, block_ht - eps])
                rotate([0, 90, 0])
                    cylinder(r = tunnel_r, h = block_wid + 2 * eps);
    }
}
```

