// Cable bridge - rectangular block with 3 semicircular tunnels along Y
// Print orientation: flat on bed, tunnels facing up

$fn = 64;

// ---- Block dimensions ----
block_len   = 60;   // X length (mm)
block_wid   = 50;   // Y width (mm)
block_h     = 15;   // Z height (mm)

// ---- Tunnel dimensions ----
tunnel_d    = 10;   // tunnel diameter (mm)
tunnel_n    = 3;    // number of tunnels
tunnel_pitch= 16;   // centre-to-centre spacing along X (mm)

// ---- Cutting overlap ----
eps         = 0.5;  // extension past faces for clean differences (mm)

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels along Y at floor level
    for (i = [0 : tunnel_n - 1]) {
        x = (i - (tunnel_n - 1) / 2) * tunnel_pitch;
        // cylinder axis along Y at z = 0; upper half lies in the block
        translate([x, 0, 0])
            cylinder(d = tunnel_d, h = block_wid + 2*eps, $fn = 64);
    }
}
