```openscad
// Tapered riser block - solid square frustum with a square pocket in the top face
// Print orientation: bottom face on the bed (z = 0), top face at z = height

// ---------------- Parameters ----------------
bottom_w     = 80;   // bottom square side length (mm)
bottom_h     = 80;   // bottom square side length (mm)
top_w        = 40;   // top square side length (mm)
top_h        = 40;   // top square side length (mm)
height       = 30;   // block height (mm)
pocket_w     = 30;   // pocket side length (mm)
pocket_d     = 8;    // pocket depth from top face (mm)
overlap      = 0.01; // small overlap so the hull fuses the two solids
$fn          = 64;   // curve resolution (set per rules, no curves here)

// ---------------- Model ----------------
difference() {
    // Square frustum built as two fused blocks with overlapping faces
    union() {
        // bottom block: from z = 0 up to the overlap plane
        translate([-bottom_w/2, -bottom_h/2, 0])
            cube([bottom_w, bottom_h, overlap]);
        // top block: from the overlap plane up to z = height
        translate([-top_w/2, -top_h/2, height - overlap])
            cube([top_w, top_h, overlap]);
        // sloped middle block, extended slightly past both end planes
        hull() {
            translate([-bottom_w/2, -bottom_h/2, -overlap])
                cube([bottom_w, bottom_h, overlap*2]);
            translate([-top_w/2, -top_h/2, height - overlap*2])
                cube([top_w, top_h, overlap*2]);
        }
