// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len    = 120;   // plate length along X (mm)
plate_wid    = 80;    // plate width along Y (mm)
plate_thk    = 2;     // plate thickness (mm), z = 0..2

rib_thk      = 2;     // rib thickness along X (mm)
rib_h        = 6;     // rib height from top of plate (mm), z = 2..8
rib_count    = 3;     // number of ribs
rib_pitch    = 30;    // centre-to-centre spacing of ribs (mm)
rib_offset   = 30;    // distance of outer ribs from plate ends (mm)

eps          = 0.5;   // overlap for clean boolean unions (mm)
$fn          = 64;    // curve resolution (no curves here, set per rules)

// Derived
rib_x0 = -plate_len/2 + rib_offset;   // centre X of leftmost rib
rib_xi = rib_x0 + (i - 1) * rib_pitch; // centre X of i-th rib (i = 0..2)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([rib_xi - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
