```openscad
// Stiffened cover panel - flat plate with 3 transverse ribs
// Print orientation: plate flat on bed (z = 0), ribs pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 120;   // length along X (mm)
plate_wid   = 80;    // width along Y (mm)
plate_thk   = 2;     // thickness along Z (mm), z = 0..2

// ---- Ribs ----
rib_count   = 3;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 6;     // rib height from top of plate (mm), z = 2..8
rib_pitch   = 30;    // centre-to-centre spacing along X (mm)
rib_offset  = 30;    // distance of outer ribs from plate ends (mm)

// ---- Derived ----
rib_x0 = -plate_len/2 + rib_offset;   // centre X of leftmost rib
rib_h_total = plate_thk + rib_h;      // absolute height of ribs (z = 2..8)

// ---- Modelling overlap ----
eps = 0.5;          // half-width of cutter so ribs merge into plate

module stiffened_panel() {
    union() {
        // Base plate, centred in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Ribs running full width along Y
        for (i = [0 : rib_count - 1]) {
            translate([rib_x0 + (i - (rib_count - 1)/2) * rib_pitch - rib_thk/2,
                       -plate_wid/2, 0])
                cube([rib_thk + eps, plate_wid, rib_h_total]);
        }
    }
}

stiffened_panel();
```

