// Cable bridge - rectangular block with a semicircular tunnel along Y at floor level
// Print orientation: block stands on the bed (z = 0), tunnel opens downward

$fn = 96;

// ---- Block dimensions ----
block_len    = 60;    // length along X (mm)
block_wid    = 50;    // width along Y (mm)
block_h      = 12;    // height along Z (mm)

// ---- Tunnel dimensions ----
tunnel_d     = 8;     // cylinder diameter (mm); radius = 4 mm
tunnel_axis_y = 0;    // cylinder axis Y position (mm)

// ---- Cutting overlap ----
eps          = 0.5;   // extension of cutters past faces (mm)

module tunnel_cutter() {
    // Cylinder along local Z (which is Y in world), inverted so the
    // semicircle faces downward toward z = 0
    translate([0, tunnel_axis_y, 0])
        rotate([90, 0, 0])
            cylinder(r = tunnel_d / 2, h = block_wid + 2 * eps, center = true);
}

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    tunnel_cutter();
}
```

