// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;     // knuckle diameter
knuckle_n   = 5;     // number of segments
knuckle_x0  = -12;   // first segment start (5 * 12 mm segments)
knuckle_y   = 15;    // knuckle axis Y position (on +Y edge)
knuckle_z   = 4;     // knuckle axis height above bed

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0, 2, 4]) {
            translate([knuckle_x0 + i * 12, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = 10, $fn = 64);
        }
    }

    // Pin holes through every knuckle
    for (i = [0, 2, 4]) {
        translate([knuckle_x0 + i * 12, knuckle_y, knuckle_z])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = plate_thk + 2*eps, $fn = 64);
    }
}
```

