// Leaf of a pin hinge
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 60;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter
knuckle_z   = 4;    // knuckle axis height above plate
knuckle_h   = 8;    // knuckle height above axis
knuckle_ds  = 12;   // centre-to-centre spacing along X
knuckle_n   = 5;    // number of segments
pin_d       = 2.5;  // pin hole diameter
eps         = 0.5;  // overshoot for clean cuts

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0, 2, 4]) {
            x = (i - 2) * knuckle_ds;
            translate([x, plate_wid/2, 0])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
        }
    }

    // Pin hole along the common axis of the knuckles
    translate([-knuckle_n*knuckle_ds/2, plate_wid/2, 0])
        cylinder(d = pin_d, h = plate_thk + 2*eps, $fn = 96);
}
