```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 to plate_t

// ---- Parameters ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 18;   // distance of inner points from centre
point_n   = 6;    // number of points (evenly spaced)
plate_t   = 4;    // plate thickness
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline: outer points at 0°, 60°, ... ; inner points at 30°, 90°, ...
    linear_extrude(height = plate_t)
        polygon(points = [
            for (i = [0 : point_n - 1])
                [outer_r * cos(30 * i), outer_r * sin(30 * i)];
            for (i = [0 : point_n - 1])
                [inner_r * cos(30 * i + 15), inner_r * sin(30 * i + 15)];
        ]);

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
```

