// Star-shaped indexing wheel - 6-pointed flat plate
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
outer_r   = 30;   // distance of outer points from centre (mm)
inner_r   = 18;   // distance of inner points from centre (mm)
points    = 6;    // number of spikes (outer and inner)
thickness = 4;    // plate thickness (mm)
hole_d    = 8;    // central through-hole diameter (mm)
eps       = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 96;         // resolution for curved shapes

// ---------- Model ----------
difference() {
    // Star outline: outer points at 0, 60, 120... deg,
    // inner points at 30, 90, 150... deg
    linear_extrude(height = thickness)
        polygon([
            for (i = [0 : points - 1])
                each [
                    [outer_r * cos(i * 60), outer_r * sin(i * 60)],
                    [inner_r * cos(i * 60 + 30), inner_r * sin(i * 60 + 30)]
                ]
        ]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}
