top_h      = 25;    // top square height above bed (mm)
pocket_w   = 60;    // square pocket side length (mm)
pocket_d   = 5;     // square pocket depth from top face (mm)
eps        = 0.5;   // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Solid square frustum, edges parallel to X and Y
    hull() {
        translate([-bottom_w/2, -bottom_w/2, bottom_h])
            cube([bottom_w, bottom_w, top_h - bottom_h]);
        translate([-top_w/2, -top_w/2, top_h])
            cube([top_w, top_w, eps]);   // small block above top face for a clean hull
    }

    // Square pocket centred on the top face
    translate([-pocket_w/2, -pocket_w/2, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
