// Tapered riser block for setting a beaker higher
// Print orientation: bottom face on the bed (z = 0), pocket opening upward (+Z)

// ---------------- Parameters (mm) ----------------
riser_height    = 25;    // height of the frustum (z = 0 to z = 25)
bottom_side     = 60;    // side length of the square base at z = 0
top_side        = 40;    // side length of the square top face at z = 25
pocket_side     = 30;    // side length of the square pocket
pocket_depth    = 5;     // depth of the pocket into the top face
overcut         = 0.5;   // extra length of cutters past faces
$fn             = 64;    // curve resolution (for consistency)

// ---------------- Derived ----------------
half_bottom = bottom_side / 2;    // 30
half_top    = top_side / 2;       // 20
// Pocket centred in XY, sitting at the top face (y runs -15..15, so it is inside the 40 mm face)

// ---------------- Model ----------------
difference() {
    // Square frustum: hull between the bottom and top faces
    hull() {
        // Base at z = 0
        translate([-half_bottom, -half_bottom, 0])
            cube([bottom_side, bottom_side, 1]);   // 1 mm thick seed
        // Top face at z = riser_height
        translate([-half_top, -half_top, riser_height])
            cube([top_side, top_side, 1]);
    }

    // Square pocket, 5 mm deep, centred on the top face
    translate([0, -pocket_side / 2, riser_height - pocket_depth])
        cube([pocket_side, pocket_side, pocket_depth + overcut]);
}
