difference() {
    union() {
        // Posts
        for (sx = [-1, 1])
            translate([sx * post_x, post_y, 0])
                cylinder(d = post_d, h = post_h);

        // Bar (slightly overlaps posts for a solid union)
        translate([bar_x0, bar_y0, post_h - 0.01])
            cube([bar_len, bar_w, bar_t + 0.01]);
    }

    // Screw holes through each post
    for (sx = [-1, 1])
        translate([sx * post_x, post_y, -eps])
            cylinder(d = screw_d, h = post_h + screw_dep + 2 * eps);
