// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 130;   // overall length along X
gauge_w     = 8;     // gauge section width (Y)
gauge_len   = 40;    // gauge section length (X)
grip_w      = 20;    // grip section width (Y)
grip_len    = 35;    // grip section length (X)
trans_len   = 10;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_grip   = grip_w / 2;
half_gauge  = gauge_w / 2;
reach       = grip_len + trans_len;   // end of grip from centre

// ---------- Model ----------
difference() {
    // Main plate
    translate([-total_len / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([
                [-total_len / 2, -half_grip],
                [ total_len / 2, -half_grip],
                [ total_len / 2,  half_grip],
                [ -total_len / 2,  half_grip]
            ]);

    // Central gauge section
    translate([-gauge_len / 2, -gauge_w / 2, eps])
        cube([gauge_len, gauge_w, thickness - 2 * eps]);

    // Grip sections at each end
    for (s = [-1, 1])
        translate([s * reach, -half_grip, eps])
            cube([grip_len, grip_w, thickness - 2 * eps]);

    // Transition regions (width changes linearly from grip to gauge)
    for (s = [-1, 1])
        translate([s * reach, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0,      half_grip],
                    [trans_len, half_gauge],
                    [-trans_len, half_gauge],
                    [0,      -half_grip]
                ]);
}
