// Flat dog-bone tensile specimen
// Print orientation: flat on bed, builds up in +Z

// ---------- Parameters ----------
thickness = 3;     // plate thickness (Z)
total_len = 130;   // overall length along X
gauge_w   = 8;     // gauge section width (Y)
gauge_len = 40;    // gauge section length (X)
grip_w    = 20;    // grip section width (Y)
grip_len  = 35;    // grip section length (X)
trans_len = 10;    // transition section length (X)
eps       = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_w / 2;
half_grip  = grip_w / 2;
a          = grip_w + 2 * trans_len;   // width at start of curve (grip end)
b          = gauge_w;                  // width at end of curve (gauge start)

// ---------- Model ----------
difference() {
    // Plate
    translate([-total_len / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon([
                [-total_len / 2, -half_grip],
                [ total_len / 2, -half_grip],
                [ total_len / 2,  half_grip],
                [ -total_len / 2,  half_grip]
            ]);

    // Gauge section
    translate([-gauge_len / 2, -half_gauge, eps])
        cube([gauge_len, gauge_w, thickness - 2 * eps]);

    // Grip sections
    for (s = [-1, 1])
        translate([s * (trans_len + grip_len), -half_grip, eps])
            cube([grip_len, grip_w, thickness - 2 * eps]);

    // Curved transitions (spline through 4 points: straight in -> straight out)
    for (s = [-1, 1])
        translate([s * trans_len, 0, 0])
            linear_extrude(thickness)
                rotate([90, 0, s * 90])
                    translate([0, grip_w / 2, 0])
                        hull() {
                            for (i = [0, 1])
                                translate([i * trans_len - 0.01, a / 2 + (b - a) / 2 * i])
                                    cube([eps, thickness, 1]);
                            for (i = [0, 1])
                                translate([i * trans_len - 0.01, b / 2 + (a - b) / 2 * i])
                                    cube([eps, thickness, 1]);
                        }
}
