// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
half_gauge = gauge_width / 2;
half_grip  = grip_width / 2;
x0         = -total_length / 2;   // left end of specimen

// Width profile seen from above (y = 0 at centreline)
function width(x) =
    if (x < x0 + grip_length)
        half_grip + (x - x0) * (half_gauge - half_grip) / transition_len;
    else if (x < x0 + grip_length + transition_len)
        half_gauge + (x - x0 - grip_length) * (half_grip - half_gauge) / transition_len;
    else if (x < x0 + grip_length + transition_len + gauge_length)
        half_grip + (x - x0 - grip_length - transition_len) *
                     (half_grip - half_gauge) / transition_len;
    else
        half_grip + (x - x0 - grip_length - transition_len - gauge_length) *
                     (half_grip - half_gauge) / transition_len;

difference() {
    // Main plate
    translate([x0, -half_grip, 0])
        cube([total_length, grip_width, thickness]);

    // Grip blocks at each end, extended past the faces for a clean cut
    for (s = [-1, 1])
        translate([x0 + s * (grip_length + transition_len), -half_grip - cut_extra, -cut_extra])
            cube([grip_length + transition_len + cut_extra * 2,
                  grip_width + 2 * cut_extra,
                  thickness + 2 * cut_extra]);
}
