    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1)/2) * knuckle_p;
        translate([x, knuckle_y, -eps])
            cylinder(d = pin_d, h = plate_thk + knuckle_z0 + 2*eps);
