top_size    = 50;       // top square side length (z = 30)
riser_h     = 30;       // total height of the frustum

// --- Pocket dimensions ---
pocket_size = 40;       // square pocket side length
pocket_d    = 8;        // square pocket depth from top face

// --- Derived / helper values ---
eps         = 0.01;     // small thickness for hull slabs, avoids coplanar faces
pocket_top_z = riser_h - pocket_d;   // z of the pocket's top face (extends past top)

// Semi-width at a given z, linearly interpolated between base and top
function semi_w(z) = (base_size + (top_size - base_size) * (z - 0) / riser_h) / 2;

difference() {
    // Tapered block: hull of two concentric squares at z = 0 and z = riser_h
    hull() {
        translate([-semi_w(0), -semi_w(0), 0])
            cube([base_size, base_size, eps]);
        translate([-semi_w(riser_h), -semi_w(riser_h), riser_h - eps])
            cube([top_size, top_size, eps]);
    }

    // Square pocket, centred, extending 0.01 mm past the top face
    translate([-pocket_size / 2, -pocket_size / 2, pocket_top_z])
        cube([pocket_size, pocket_size, pocket_d + eps]);
}
