// Tapered riser block with a square pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: X -40..40, Y -40..40, Z 0..25.

// ---------------- Parameters ----------------
base_size    = 80;   // bottom square side length (mm)
top_size     = 50;   // top square side length (mm)
height       = 25;   // block height (mm)
pocket_size  = 40;   // square pocket side length (mm)
pocket_depth = 5;    // square pocket depth from top face (mm)
overlap      = 0.01; // small overlap so the hull fuses cleanly (mm)

$fn = 64;            // not strictly needed (all faces are axis-aligned), kept per convention

// ---------------- Derived values ----------------
// The hull() curve runs from the bottom face up to overlap above the top face,
// then drops straight down to the top face thickness. That gives a true
// square frustum with flat top and bottom faces.
hull_height = height + overlap;   // height of the hull curve
pocket_z0   = height - pocket_depth;  // z of the bottom of the pocket

// ---------------- Model ----------------
difference() {
    // Tapered block: square frustum from 80x80 (z=0) up to 50x50 (z=25)
    hull() {
        // Bottom face, centred on the origin, on the bed
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 1]);

        // Top face, centred on the origin, at z = height
        // The hull curve ends at z = hull_height, so this face is buried inside,
        // which avoids any coplanar faces with the curve
        translate([-top_size / 2, -top_size / 2, height - overlap])
            cube([top_size, top_size, overlap]);
    }

    // Square pocket cut into the top face, centred, 5 mm deep
    translate([-pocket_size / 2, -pocket_size / 2, pocket_z0])
        cube([pocket_size, pocket_size, pocket_depth + 1]);
}
