// Tapered riser block (square frustum) with a square pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed using the user's coordinates: x -40..40, y -40..40, z 0..25.

$fn = 64;               // curve resolution (no curved features here)

// ---- Frustum dimensions ----
base_size    = 80;      // bottom square side length (z = 0)
top_size     = 50;      // top square side length (z = 25)
height       = 25;      // total height (z = 0 to z = 25)
overlap      = 0.01;    // small overlap so the hull fuses cleanly

