module frustum() {
    // Hull of two flat plates: a square at z = 0 and one at z = height.
    // The result is a solid with flat sloping sides and edges parallel to X/Y.
    hull() {
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, overlap]);
        translate([-top_size / 2, -top_size / 2, height - overlap])
            cube([top_size, top_size, overlap]);
    }
}

module pocket_cutter() {
    // Extend the cutter slightly above the top face so no faces are
    // exactly coplanar. With a 0.01-thick top face, 0.5 mm still leaves
    // a 4.5 mm floor under the opening.
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + 0.5]);
}

difference() {
    frustum();
    pocket_cutter();
}
