// Star-shaped indexing wheel - 8-pointed flat plate
// Print orientation: flat on bed (z = 0), building upward (+Z)

// ---------------- Parameters ----------------
outer_r   = 35;   // distance of outer points from centre (mm)
inner_r   = 21;   // distance of inner points from centre (mm)
points    = 8;    // number of points / inner vertices
thickness = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
overlap   = 0.5;  // extra length so cuts pass through faces (mm)

$fn = 96;         // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // 8-pointed star outline: outer points on +X axis, alternating with inner points
    linear_extrude(height = thickness)
        polygon([
            for (i = [0 : points - 1])
                if (i % 2 == 0)
                    [outer_r * cos(i * 360 / points),
                     outer_r * sin(i * 360 / points)]
                else
                    [inner_r * cos(i * 360 / points),
                     inner_r * sin(i * 360 / points)]
        ]);

    // Central through-hole
    translate([0, 0, -overlap])
        cylinder(d = hole_d, h = thickness + 2 * overlap);
}
