```openscad
// Tapered riser block - square frustum with a top pocket
// Print orientation: bottom face on the bed (z = 0), building upward

// ---------- Dimensions (mm) ----------
base_size    = 60;   // bottom square side length (z = 0)
top_size     = 30;   // top square side length (z = 25)
height       = 25;   // overall height of the frustum
pocket_size  = 20;   // square pocket side length on the top face
pocket_depth = 5;    // depth of the pocket from the top face

// ---------- Derived ----------
top_z = height;
// Extra cut length so the pocket always overshoots the top face,
// even if pocket_depth were zero or greater than the height.
cut_over = max(pocket_depth, height / 2) + 0.5;

// ---------- Model ----------
difference() {
    // Square frustum: hull between the bottom and top faces.
    // The faces are at z = 0 and z = height, so the hull spans that range.
    hull() {
        translate([-base_size / 2, -base_size / 2, 0])
            cube([base_size, base_size, 1]);
        translate([-top_size / 2, -top_size / 2, top_z - 1])
            cube([top_size, top_size, 2]);
    }

    // Square pocket, centred, cut from the top face downward.
    // Extended upward by 'cut_over' so the cut never stops exactly at a face.
    translate([-pocket_size / 2, -pocket_size / 2, top_z - pocket_depth])
        cube([pocket_size, pocket_size, cut_over]);
}
