bar_w = 14;       // bar width along Y
bar_t = 6;        // bar thickness (z = 20 to 26)

// --- Screw holes ---
screw_d = 4.5;    // screw hole diameter
screw_depth = 10; // screw hole depth from bottom face

// --- Helpers ---
eps = 0.5;        // overlap / cut extension

difference() {
    union() {
        // Posts
        for (i = [0 : post_n - 1]) {
            x = (i - (post_n - 1) / 2) * 2 * post_x / (post_n + 1);
            translate([x, 0, 0])
                cylinder(d = post_d, h = post_h);
        }

        // Bar
        translate([-bar_l / 2, -bar_w / 2, post_h - eps])
            cube([bar_l, bar_w, bar_t + eps]);
    }

    // Screw holes
    for (i = [0 : post_n - 1]) {
        x = (i - (post_n - 1) / 2) * 2 * post_x / (post_n + 1);
        translate([x, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + eps);
    }
}
