$fn = 64;

// ---------- Model ----------
union() {
    // Plate, centred in XY, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running full width along Y
    // (positions assigned by index to match the given 24 mm outer spacing)
    translate([0, 0, 0])
        for (i = [0 : rib_count - 1])
            rotate([0, 0, i < rib_count - 1 ? 0 : 180])
                translate([-rib_center_w/2 + i * rib_center_w/4,
