// ---- Pocket dimensions ----
pocket_w  = 32;    // pocket square side
pocket_d  = 5;     // pocket depth from top face

// ---- Clearance for clean booleans ----
eps       = 0.5;   // overshoot of cutters past faces

// Derived
total_h   = base_h + eps;          // extends past top face for the cutter

module square_frustum() {
    // hull of two coaxial squares at different heights gives a frustum
    hull() {
        translate([-base_w/2, -base_w/2, 0])
            cube([base_w, base_w, 0.01]);
        translate([-top_w/2, -top_w/2, base_h])
            cube([top_w, top_w, 0.01]);
    }
}

module pocket_cutter() {
    translate([-pocket_w/2, -pocket_w/2, base_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}

difference() {
    square_frustum();
    pocket_cutter();
}
