// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to specimen_t

$fn = 64;

// --- Dimensions (mm) ---
specimen_t   = 3;     // thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 40;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 35;    // grip section length (X)
transition_l = 10;    // transition section length (X)
eps          = 0.5;   // cutter overshoot past faces

// Derived
total_l = 2 * grip_l + gauge_l + 2 * transition_l;   // 130 mm

// Width at a given X position (linear between grip and gauge)
function width_at(x) =
    if (x < transition_l)
        grip_w + (8 - grip_w) * x / transition_l;
    else if (x < transition_l + gauge_l)
        gauge_w;
    else
        grip_w + (8 - grip_w) * (x - (transition_l + gauge_l)) / transition_l;

difference() {
    // Main plate
    translate([-total_l / 2, -grip_w / 2, 0])
        cube([total_l, grip_w, specimen_t]);

    // Central gauge section (slightly reduced overlap for clean cut)
    translate([-gauge_l / 2, -width_at(transition_l + 0.01) / 2, -eps])
        cube([gauge_l, width_at(transition_l + 0.01), specimen_t + 2 * eps]);
}
