        // Bottom flange: rectangle 14 (Y) x 15 (X), z = 0 .. 3
        translate([center_x - length_x / 2,
                   center_y - flange_w / 2,
                   0])
            cube([length_x, flange_w, flange_t]);

        // Neck: rectangle 6 (Y) x 15 (X), z = 3 .. 6 (slightly overlapped into flange)
        translate([center_x - length_x / 2,
                   center_y - neck_w / 2,
                   overlap])
            cube([length_x, neck_w, neck_h - overlap]);
