    // Screw holes
    for (i = [0 : post_n - 1]) {
        x = (i - (post_n - 1) / 2) * 2 * post_x / (post_n + 1);
        translate([x, 0, -eps])
            cylinder(d = screw_d, h = screw_depth + eps);
    }
}
