// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // width of central gauge section (Y)
gauge_length   = 40;    // length of gauge section along X
grip_width     = 19;    // width of grip sections (Y)
grip_length    = 30;    // length of each grip section along X
transition_len = 15;    // length of each grip-to-gauge transition along X

// ---- Derived ----
half_gauge = gauge_length / 2;               // 20
half_grip  = grip_length / 2;                // 15
x0         = -total_length / 2 + half_grip;  // start of left grip

// Width at a given X (linear interpolation between grip and gauge)
function width_at(x) =
    if (x < 0) grip_width
    else if (x > half_gauge) grip_width
    else gauge_width;

difference() {
    // Main body
    translate([-total_length / 2, -thickness / 2, 0])
        linear_extrude(thickness)
            polygon(points = [
                [x0, -half_grip], [x0, half_grip],
                [total_length / 2 - half_grip, half_grip],
                [total_length / 2 - half_grip, -half_grip]
            ]);

    // Cut out the two transition regions (lower width -> higher width)
    for (s = [-1, 1]) {
        translate([s * (x0 + half_grip), -1, 0])
            linear_extrude(thickness + 0.5)
                polygon(points = [
                    [0, -transition_len / 2],
                    [0,  transition_len / 2],
                    [half_gauge, transition_len / 2],
                    [half_gauge, -transition_len / 2]
                ]);
    }
}
