// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // width of central gauge section (Y)
gauge_length   = 40;    // length of gauge section along X
grip_width     = 19;    // width of grip sections (Y)
grip_length    = 30;    // length of each grip section along X
transition_len = 15;    // length of each grip-to-gauge transition along X

// ---- Derived ----
left_x   = -(total_length / 2) + grip_length;    // start of left transition
middle_x = -(total_length / 2) + grip_length + transition_len; // gauge start
right_x  = total_length / 2 - grip_length;       // end of right transition

// ---- Model ----
module specimen() {
    difference() {
        // Body
        hull() {
            // left grip
            translate([-(total_length / 2), -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
            // right grip
            translate([right_x, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        // Cut out gauge and transitions
        translate([-(total_length / 2) + grip_length, -transition_len / 2, 0])
            linear_extrude(transition_len + 1)
                polygon([
                    [0, -transition_len / 2],
                    [gauge_length + transition_len, -transition_len / 2],
                    [gauge_length + transition_len, transition_len / 2],
                    [0, transition_len / 2]
                ]);
    }
}

specimen();
