gauge_length       = 30;    // gauge section length (X)

// transition sections (between grip and gauge)
transition_width   = 10;    // transition width at the gauge end
transition_length  = 10;    // transition length (X)

// ---------- Derived ----------
half_width_grip    = grip_width  / 2;
half_width_gauge   = gauge_width / 2;
half_width_trans   = transition_width / 2;

// ---------- Model ----------
union() {
    // left grip
    translate([-total_length / 2, -half_width_grip, 0])
        cube([grip_length, grip_width, specimen_thickness]);

    // left transition
    translate([-total_length / 2 + grip_length, -half_width_trans, 0])
        cube([transition_length, transition_width, specimen_thickness]);

    // gauge section
    translate([-total_length / 2 + grip_length + transition_length,
               -half_width_gauge, 0])
        cube([gauge_length, gauge_width, specimen_thickness]);

    // right transition
    translate([total_length / 2 - grip_length - transition_length,
               -half_width_trans, 0])
        cube([transition_length, transition_width, specimen_thickness]);

    // right grip
    translate([total_length / 2 - grip_length, -half_width_grip, 0])
        cube([grip_length, grip_width, specimen_thickness]);
}
