// T-shaped nut that slides into an aluminium extrusion slot
// Print orientation: flat on bed, flange at z = 0, neck builds upward

// ---------------- Parameters ----------------
flange_width = 14;    // flange width along Y (mm)
flange_t     = 2.5;   // flange thickness along Z (mm)
neck_width   = 7;     // neck width along Y (mm)
neck_top_z   = 5.5;   // top of neck along Z (mm)
screw_d      = 3.4;   // screw hole diameter (mm)
length_x     = 12;    // extrusion slot length along X (mm)
eps          = 0.5;   // cutter overshoot past faces (mm)
$fn          = 96;    // curve resolution

// Derived
neck_h      = neck_top_z - flange_t;   // neck height above flange
total_h     = neck_top_z;              // overall height

// ---------------- Profile (in YZ) ----------------
// 2D (x, y) -> (Y, Z); rotate so extrusion runs along +X
module profile_2d() {
    polygon(points = [
        [-flange_width/2, 0],
        [ flange_width/2, 0],
        [ flange_width/2, flange_t],
        [ neck_width/2,  flange_t],
        [ neck_width/2,  neck_top_z],
        [-neck_width/2,  neck_top_z],
        [-neck_width/2,  flange_t],
        [-flange_width/2, flange_t]
    ]);
}

// ---------------- Part ----------------
difference() {
    // T profile, extruded along X, centred in X and Y
    rotate([90, 0, 90])
        linear_extrude(height = length_x)
            profile_2d();

    // Screw hole: vertical cylinder through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
}
