// Tapered riser block - square frustum with a square pocket
// Print orientation: bottom face on the bed (z = 0), building upward.
// Placed at the user's coordinates: X -50 .. 50, Y -50 .. 50, Z 0 .. 20.

$fn = 64;               // curve resolution (no curved features here)

// ---- Dimensions (mm) ----
base_w    = 100;        // bottom face side length
base_h    = 0;          // bottom face height (z = 0)
top_w     = 70;         // top face side length
top_h     = 20;         // top face height (z = 20)
pocket_w  = 62;         // pocket side length
pocket_d  = 5;          // pocket depth, measured from the top face
eps       = 0.5;        // overshoot for clean boolean cuts

// ---- Derived ----
pocket_top_z = top_h - pocket_d;   // bottom of the pocket (z = 15)
pocket_h     = pocket_d + eps;     // extra height so the cut passes the top face

module tapered_block() {
    // Hull of two aligned squares gives a solid frustum with flat sides.
    // Each square is thickened by eps so the hull has no coplanar faces.
    hull() {
        translate([-base_w / 2 - eps, -base_w / 2 - eps, base_h])
            cube([base_w + 2 * eps, base_w + 2 * eps, eps]);
        translate([-top_w / 2 - eps, -top_w / 2 - eps, top_h - eps])
            cube([top_w + 2 * eps, top_w + 2 * eps, eps]);
    }
}

difference() {
    tapered_block();

    // Square pocket cut into the top face, centred on the origin
    translate([-pocket_w / 2, -pocket_w / 2, pocket_top_z])
        cube([pocket_w, pocket_w, pocket_h]);
}
