            cube([bottom_w, bottom_w, bottom_h + 1]);  // tiny seed at z = 0
        translate([-top_w/2, -top_w/2, top_h])
            cube([top_w, top_w, 1]);                   // tiny seed at z = 25
    }

    // Square pocket cut into the top face, centred, edges parallel to X and Y
    translate([0, 0, top_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
