// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness   = 3;     // specimen thickness (Z)
total_len   = 140;   // overall length along X
gauge_w     = 6;     // gauge section width (Y)
gauge_len   = 50;    // gauge section length (X)
grip_w      = 19;    // grip section width (Y)
grip_len    = 30;    // grip section length (X)
trans_len   = 15;    // transition section length (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
half_gauge = gauge_len / 2;
half_grip  = grip_len / 2;
// grip end x = -total_len/2 + half_grip, gauge end x = +total_len/2 - half_grip
x0 = -total_len / 2 + half_grip + trans_len;   // gauge start X
x1 = x0 + gauge_len;                            // gauge end X

// ---------- Width profile (seen from above) ----------
function w(px) =
    if (px < -half_grip) grip_w;
    else if (px < -half_grip + trans_len)
        grip_w + (6 - grip_w) * (px - (-half_grip + trans_len)) / trans_len;
    else if (px < half_grip - trans_len) gauge_w;
    else if (px < half_grip)
        gauge_w + (grip_w - gauge_w) * (px - (half_grip - trans_len)) / trans_len;
    else grip_w;

// ---------- Model ----------
difference() {
    // Main plate
    linear_extrude(height = thickness)
        translate([-total_len / 2, -50, 0])
            rotate([90, 0, 0])
                linear_extrude(height = 100)
                    drawpolygon(points = [for (i = [0 : 99]) [total_len * i / 99, w(total_len * i / 99)]]);

    // Central relief, centered on origin, extends past top/bottom faces
    translate([0, 0, -eps])
        linear_extrude(height = thickness + 2 * eps)
            translate([-half_gauge, -gauge_w / 2])
                square([gauge_len / 2, gauge_w]);
}
